public class DialogueNode {
    private String text;
    private List<DialogueOption> options;

    public DialogueNode(String text) {
        this.text = text;
        this.options = new ArrayList<>();
    }

    public void addOption(String optionText, DialogueNode nextNode) {
        options.add(new DialogueOption(optionText, nextNode));
    }

    public void display() {
        System.out.println(text);
        for (int i = 0; i < options.size(); i++) {
            System.out.println((i + 1) + ". " + options.get(i).getText());
        }
    }

    public DialogueNode getNextNode(int choice) {
        return options.get(choice - 1).getNextNode();
    }
}

public class DialogueOption {
    private String text;
    private DialogueNode nextNode;

    public DialogueOption(String text, DialogueNode nextNode) {
        this.text = text;
        this.nextNode = nextNode;
    }

    public String getText() {
        return text;
    }

    public DialogueNode getNextNode() {
        return nextNode;
    }
}
